class TokenAuthenticator(private val store: AuthStore, private val api: AuthApi) : Authenticator {
    private val lock = Any()

    override fun authenticate(route: Route?, response: Response): Request? = synchronized(lock) {
        if (responseCount(response) >= 2) return null
        val currentAccess = store.getAccessToken()
        val failedHeader = response.request.header("Authorization")
