```c
size_t val_offset = colon_offset + 2;
while (len + chunk_len + 1 > cap) {
    size_t next_cap = cap * 2;
    char *tmp = realloc(buf, next_cap);
    if (!tmp) {
        free(buf);
        return -1;
    }
    buf = tmp;
    cap = next_cap;
}
memcpy(buf + len, chunk, chunk_len);
len += chunk_len;
buf[len] = '\0';
