ALTER TABLE customers ADD COLUMN IF NOT EXISTS organization_name TEXT;

CREATE OR REPLACE FUNCTION sync_org_company_cols() RETURNS trigger AS $$
BEGIN
    IF NEW.organization_name IS NULL THEN
        NEW.organization_name := NEW.company_name;
    ELSIF NEW.company_name IS NULL OR NEW.organization_name IS DISTINCT FROM OLD.organization_name THEN
        NEW.company_name := NEW.organization_name;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_sync_org_company
BEFORE INSERT OR UPDATE ON customers
FOR EACH ROW EXECUTE FUNCTION sync_org_company_cols();
-- (Backfill in batches, deploy v2 reading/writing organization_name, then drop company_name in Release 2!)
