static TagTable *cached_table = NULL;

Datum corp_normalize_tag(PG_FUNCTION_ARGS) {
    if (cached_table == NULL) {
        cached_table = (TagTable *) palloc(sizeof(TagTable));
        init_tag_table(cached_table);
