```go
type Gen struct {
    mu        sync.Mutex
    baseWall  int64
    baseMono  time.Time
    nodeID    int64
    lastMs    int64
    seq       int64
}

func NewGen(nodeID int64) *Gen {
    now := time.Now()
    return &Gen{
        baseWall: now.UnixMilli(),
        baseMono: now,
        nodeID:   nodeID & 0x3ff,
    }
}

func (g *Gen) NextID() int64 {
    g.mu.Lock()
    defer g.mu.Unlock()

    now := g.baseWall + time.Since(g.baseMono).Milliseconds()
    if now <= g.lastMs {
        g.seq = (g.seq + 1) & 0xfff
        if g.seq == 0 {
            g.lastMs++ // Logical clock tick if >4096 IDs/ms
        }
    } else {
        g.seq = 0
        g.lastMs = now
    }
    return ((g.lastMs - epochMs) << 22) | (g.nodeID << 12) | g.seq
}
```

