```c
SSL *accept_tls_client(SSL_CTX *ctx, int client_fd) {
    BIO *bio = BIO_new_socket(client_fd, BIO_NOCLOSE);
    SSL *ssl = SSL_new(ctx);
    if (!ssl || !bio) {
        goto err;
    }
    SSL_set_bio(ssl, bio, bio);
    bio = NULL; /* Ownership transferred to ssl; SSL_free(ssl) frees it! */

    if (SSL_accept(ssl) <= 0) {
        goto err;
    }
    return ssl;

err:
    SSL_free(ssl);
    BIO_free_all(bio);
    return NULL;
}
```

