```c
char buf[512];
size_t off = 0;
for (int i = 0; i < n_labels; i++) {
    int n = snprintf(buf + off, sizeof(buf) - off, "%s=\"%s\",", keys[i], vals[i]);
    if (n < 0 || (size_t)n >= sizeof(buf) - off) {
        return -ENOBUFS; // truncated or encoding error
    }
    off += (size_t)n;
