public class FrameValidatorHandler extends ChannelInboundHandlerAdapter {
    @Override
    public void channelRead(ChannelHandlerContext ctx, Object msg) {
        ByteBuf buf = (ByteBuf) msg;
        try {
            if (buf.readableBytes() < 8) {
                throw new CorruptedFrameException("Frame too short");
            }
            ByteBuf view = buf.slice(8, buf.readableBytes() - 8); // refCnt stays 1
            if (!verifyCrc32(buf, view)) {
