pub struct TelemetryHdr {
    pub seq_no: u64,
    pub ts_nanos: u64,
    pub flags: u32,
    pub pad: u32,
}

pub fn decode_after_eth(frame: &[u8]) -> Option<&TelemetryHdr> {
    if frame.len() < 14 + std::mem::size_of::<TelemetryHdr>() {
        return None;
    }
    // Ethernet header is 14 bytes -> payload starts at byte offset 14!
    let ptr = unsafe { frame.as_ptr().add(14) as *const TelemetryHdr };
