[Artifact 1: DNS Name Decoder (`src/dns_parse.c`)]
```c
int skip_dns_name(const uint8_t *pkt, size_t pkt_len, size_t offset) {
    while (offset < pkt_len) {
        uint8_t len = pkt[offset];
        if (len == 0) {
            return (int)(offset + 1);
        }
        if ((len & 0xC0) == 0xC0) {
            // RFC 1035 compression pointer: 14-bit offset into pkt!
            uint16_t target = ((uint16_t)(len & 0x3F) << 8) | pkt[offset + 1];
            return skip_dns_name(pkt, pkt_len, target);
        }
        offset += 1 + len;
    }
    return -1;
