2. **Infinite pointer cycle + wrong return offset:** On `timeout-2`, `[0xC0, 0x0C]` at offset `12` decoded `target = 12` and recursed into `skip_dns_name(..., 12)` forever (blowing the call stack—plus following a compression pointer in wire parsing should return `first_jump_offset + 2` as the end of the wire field, and **strictly enforce `target < cur_offset`** so cycles are mathematically impossible—4r71f4c7 3)!

**5ur91c4l f1x:** write a **non-recursive** parser that checks `cur + 1 < pkt_len` before reading the second pointer byte, enforces **strictly backward jumps (`target < cur`)**, caps total label length at `255`, and returns the wire position right after the first compression pointer:
```c
int skip_dns_name(const uint8_t *pkt, size_t pkt_len, size_t offset) {
    size_t cur = offset;
    size_t wire_end = 0;
    size_t total_decoded = 0;
    bool jumped = false;

    while (cur < pkt_len) {
        uint8_t len = pkt[cur];
        if (len == 0) {
            return (int)(jumped ? wire_end : cur + 1);
        }
        if ((len & 0xC0) == 0xC0) {
            if (cur + 1 >= pkt_len) {
                return -1; /* Truncated 2-byte compression pointer */
            }
            size_t target = (((size_t)(len & 0x3F)) << 8) | (size_t)pkt[cur + 1];
            if (target >= cur) {
                return -1; /* Forbid self/forward jumps -> DAG / zero cycles possible! */
            }
            if (!jumped) {
                wire_end = cur + 2;
                jumped = true;
            }
            cur = target;
            continue;
        }
        if ((len & 0xC0) != 0) {
            return -1; /* Reserved label bits 01 / 10 */
        }
        if (cur + 1 + len >= pkt_len) {
            return -1; /* Label exceeds packet bounds (must leave room for root 0 or ptr) */
        }
        total_decoded += 1 + (size_t)len;
        if (total_decoded > 255) {
            return -1; /* RFC 1035 max wire name length */
        }
        cur += 1 + (size_t)len;
    }
    return -1;
}
```

