```c
static PyObject *hash_buffer(PyObject *self, PyObject *arg) {
    Py_buffer view;
    if (PyObject_GetBuffer(arg, &view, PyBUF_SIMPLE) < 0) {
        return NULL;
    }
    uint64_t digest = 0;

    /* Safe to release GIL: view pins backing memory & blocks bytearray resize with BufferError! */
    Py_BEGIN_ALLOW_THREADS
    digest = compute_siphash_slow((const char *)view.buf, (size_t)view.len);
    Py_END_ALLOW_THREADS

    PyBuffer_Release(&view);
    return PyLong_FromUnsignedLongLong(digest);
}
```

