    if (pkt_len < 14 + 20) {
        return -1;
    }
    uint8_t ver_ihl = pkt[14];
    uint8_t version = ver_ihl >> 4;
    uint8_t ihl = ver_ihl & 0x0F;
    if (version != 4 || ihl < 5) {
        return -1; /* Reject non-IPv4 and illegal IHL < 20 bytes */
    }
    size_t ip_hdr_bytes = (size_t)ihl * 4;
    if (pkt_len < 14 + ip_hdr_bytes + 20) {
        return -1; /* Ensure full variable IP header + 20B TCP header fit in pkt_len! */
    }
    if (pkt[14 + 9] != IPPROTO_TCP) {
        return -1;
    }
    uint16_t raw_port = 0;
    memcpy(&raw_port, pkt + 14 + ip_hdr_bytes + 2, sizeof(raw_port));
    *out_dport = ntohs(raw_port);
    return 0;
}
